css:
.combination-lock {
  position: relative;
  display: flex;
  gap: 1rem;
  user-select: none;
}

.dial {
  width: 34px;
  height: 120px;
  overflow: hidden;
  perspective: 500px;
  border-radius: 10px / 250px;
  outline: solid 2px #0005;
  outline-offset: 1px;
  filter: drop-shadow(4px 0 0px #0006) drop-shadow(8px -1px 1px #0003)
    drop-shadow(6px 8px 2px #0003)
    drop-shadow(12px 16px 32px rgba(255, 231, 201, 0.5))
    drop-shadow(-12px -16px 64px rgba(255, 231, 201, 0.5)) contrast(1.6);
  box-shadow:
    -2px -3px 1px 2px #1115,
    0 -3px 2px 2px #fff,
    0 2px 2px 2px #eee,
    0 4px 1px 3px #0009;
}

.dial::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 50% 50%, #000d 45%, 47.5%, #fff0),
    linear-gradient(to bottom, #fffd, 50%, #111);

  background-position:
    0 14px,
    0 0;
  background-repeat: no-repeat;
  mix-blend-mode: soft-light;
  pointer-events: none;
}

.nonagon {
  width: 100%;
  height: 100%;
  position: relative;
  top: 36px;
  transform-style: preserve-3d;
  transform-origin: 0 24px;
  transform: rotateX(0deg);
  animation: rotate-anim 6s ease infinite;
  animation-delay: calc(var(--i) * 0.11s);
}

@keyframes rotate-anim {
  0%,
  10% {
    transform: rotateX(-360deg);
  }

  20%,
  60% {
    transform: rotateX(-216deg);
  }

  70%,
  100% {
    transform: rotateX(0deg);
  }
}

.face {
  position: absolute;
  display: grid;
  place-items: center;
  width: 34px;
  height: 47px;

  background-color: #bdbab7;
  box-shadow:
    0 -3px 5px 1px #0008,
    0 0px 4px 3px #fffe;

  font-family: "Lucida Console", Courier, monospace;
  font-size: 1.75em;
  text-shadow:
    0.5px 0.5px 0.5px #fff,
    -0.5px -0.5px 0.5px #000;
  color: #888;
  -webkit-text-stroke: 01px #aaa6;
}

.face::before,
.face::after {
  content: "";
  position: absolute;
  height: 100%;
  width: 4px;
  border: 0.5px solid #0005;
}
.face::before {
  left: 0;
  background-color: #fff9;
  filter: blur(0.5px);
}
.face::after {
  right: 0;
  background-color: #0004;
  filter: blur(0.5px);
}

.face span {
  position: absolute;
  pointer-events: none;
}

.face .radio {
  position: absolute;
  width: 100%;
  height: 100%;
  cursor: pointer;
  appearance: none;
  opacity: 0.5;
  z-index: 0;
}

.face-0 {
  transform: rotateX(0deg) translateZ(71px);
}
.face-1 {
  transform: rotateX(-36deg) translateZ(71px);
}
.face-2 {
  transform: rotateX(-72deg) translateZ(71px);
}
.face-3 {
  transform: rotateX(-108deg) translateZ(71px);
}
.face-4 {
  transform: rotateX(-144deg) translateZ(71px);
}
.face-5 {
  transform: rotateX(-180deg) translateZ(71px);
}
.face-6 {
  transform: rotateX(-216deg) translateZ(71px);
}
.face-7 {
  transform: rotateX(-252deg) translateZ(71px);
}
.face-8 {
  transform: rotateX(-288deg) translateZ(71px);
}
.face-9 {
  transform: rotateX(-324deg) translateZ(71px);
}
